declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Request : BOOL;
    Trip : BOOL;
    Preset : USINT;
END_VAR
VAR_OUTPUT
    Ready : BOOL;
    Count : USINT;
END_VAR
VAR
END_VAR

implementation:
IF Trip OR NOT Request OR (Preset < USINT#1) OR (Preset > USINT#5) THEN
    Count := USINT#0;
    Ready := FALSE;
ELSE
    IF Count < Preset THEN
        Count := Count + USINT#1;
    END_IF
    Ready := (Count >= Preset);
END_IF
